-- Batch 2: IoC/DI, JWT filter chain, REST API design (from Google Drive bootcamp slides)

insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('inversion-of-control-and-dependency-injection', 'Inversion of Control & Dependency Injection: The Bean I Kept Recreating', 'Six classes, one Person object, one `new Person(...)` copy-pasted six times. That''s the problem IoC actually solves — not an abstract principle, a concrete duplication bug.', 'backend-notes', ARRAY['Spring Boot', 'Java', 'Architecture']::text[], ARRAY['Java', 'Spring Boot']::text[], '2026-07-10', null, 7, 'intermediate', 'Hen Heang', false, '🔌', $json$[{"type":"paragraph","text":"Inversion of Control sounds like an abstract architecture principle until you hit the concrete problem it solves: six classes all need the same Person object, so six classes each call `new Person(\"Jon\", \"Snow\")`. Now you want to change the name — you're editing six places. That's the actual motivating problem, not a diagram."},{"type":"heading","level":2,"text":"The problem before IoC","id":"the-problem"},{"type":"code","language":"java","code":"public class ClassA {\n    public static void main(String[] args) {\n        Person person = new Person(\"Jon\", \"Snow\");\n        System.out.println(person);\n    }\n}\n// ClassB, ClassC, ClassD... each need their own \"Jon Snow\"\n// -> each one does its own \"new Person(\\\"Jon\\\", \\\"Snow\\\")\""},{"type":"callout","variant":"info","text":"In IoC, objects do not create the other objects they depend on. Instead, a container creates and configures those dependencies externally, then injects them into whatever needs them — one Person, shared, instead of six copies drifting apart."},{"type":"heading","level":2,"text":"Two ways to register a bean","id":"registering-a-bean"},{"type":"code","language":"java","filename":"Component + ComponentScan","code":"@Component\npublic class Person {\n    private String firstName;\n    private String lastName;\n    // constructor, setter, getter...\n}\n\n@ComponentScan(\"your_package\")\npublic class Config {}"},{"type":"code","language":"java","filename":"Configuration + Bean","code":"@Configuration\npublic class Config {\n    @Bean\n    public Person person() {\n        return new Person(\"jon\", \"snow\");\n    }\n}"},{"type":"paragraph","text":"@Component tells the container to create one bean of that type automatically during a classpath scan. @Configuration + @Bean is more explicit — a method you write yourself decides how the bean gets constructed, which matters when construction needs logic beyond a plain constructor call."},{"type":"heading","level":2,"text":"Singleton by default — and why that surprises people","id":"singleton-scope"},{"type":"code","language":"java","code":"Person personOne = applicationContext.getBean(Person.class);\nPerson personTwo = applicationContext.getBean(Person.class);\npersonOne.setFirstName(\"Kok\");\n\nSystem.out.println(personOne); // Person(firstName=Kok, lastName=Son)\nSystem.out.println(personTwo); // Person(firstName=Kok, lastName=Son) -- same object"},{"type":"callout","variant":"warning","title":"Singleton is the default scope","text":"Every bean in Spring is a singleton unless you mark it @Scope(\"prototype\"). personOne and personTwo above are the exact same instance — mutating one mutates both. This is the source of a specific class of bug: storing per-request state on a singleton service field."},{"type":"heading","level":2,"text":"Three ways to inject a dependency","id":"three-injection-types"},{"type":"code","language":"java","filename":"Constructor injection","code":"@Component\npublic class Car {\n    private final Person person;\n\n    public Car(Person person) { // no @Autowired needed\n        this.person = person;\n    }\n}"},{"type":"code","language":"java","filename":"Field injection — not recommended","code":"@Component\npublic class Car {\n    @Autowired\n    private Person person; // required dependencies are invisible from outside the class\n}"},{"type":"callout","variant":"best-practice","title":"Spring's own recommendation","text":"Constructor injection for mandatory dependencies, setter injection for optional ones. Field injection is the one to avoid: the list of required dependencies is invisible from outside the class, the object can be constructed in a half-initialized state, and it's harder to unit test without a Spring context."},{"type":"paragraph","text":"That single duplication problem — six classes, one Person, one hardcoded value drifting out of sync — is the whole justification for the container, the bean, and every annotation built around them. Everything else is mechanics."}]$json$::jsonb, 6) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('jwt-authentication-anatomy-of-a-filter-chain', 'JWT Authentication: Anatomy of a Filter Chain', 'The token is only half the story. The half that actually decides whether a request is authenticated is a filter that runs before your controller ever sees the request.', 'architecture', ARRAY['Spring Boot', 'Security', 'JWT', 'Java']::text[], ARRAY['Java', 'Spring Boot']::text[], '2026-07-10', null, 9, 'advanced', 'Hen Heang', true, '🔐', $json$[{"type":"paragraph","text":"A JWT is just a signed string with three parts: a header (signing algorithm + token type), a payload (the claims — usually the subject and an expiry), and a signature that lets the server verify the payload hasn't been tampered with. The interesting engineering isn't the token format — it's the filter that runs on every request to check it."},{"type":"heading","level":2,"text":"Where the token comes from","id":"parsing-the-token"},{"type":"code","language":"java","filename":"AuthTokenFilter.java","code":"private String parseJwt(HttpServletRequest request) {\n    String headerAuth = request.getHeader(\"Authorization\");\n    if (StringUtils.hasText(headerAuth) && headerAuth.startsWith(\"Bearer \")) {\n        return headerAuth.substring(7, headerAuth.length());\n    }\n    return null;\n}"},{"type":"callout","variant":"tip","text":"That substring(7) is skipping past the literal string \"Bearer \" (7 characters, including the trailing space) to get to the raw token. If you've ever wondered exactly what that magic number means in an Authorization header — that's it."},{"type":"heading","level":2,"text":"The filter that runs before your controller","id":"the-filter"},{"type":"code","language":"java","filename":"AuthTokenFilter.java","code":"public class AuthTokenFilter extends OncePerRequestFilter {\n\n    @Autowired private JwtUtils jwtUtils;\n    @Autowired private UserService userDetailsService;\n\n    @Override\n    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,\n                                     FilterChain filterChain) throws ServletException, IOException {\n        try {\n            String jwt = parseJwt(request);\n            if (jwt != null && jwtUtils.validateJwtToken(jwt)) {\n                String username = jwtUtils.getUserNameFromJwtToken(jwt);\n                UserDetails userDetails = userDetailsService.loadUserByUsername(username);\n\n                UsernamePasswordAuthenticationToken authentication =\n                    new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());\n                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));\n                SecurityContextHolder.getContext().setAuthentication(authentication);\n            }\n        } catch (Exception e) {\n            logger.error(\"Cannot set user authentication: {}\", e);\n        }\n        filterChain.doFilter(request, response);\n    }\n}"},{"type":"paragraph","text":"This is the piece that actually answers the question I explained in [[prompt-engineering-for-backend-developers]]'s worked example: authentication ends up non-null in SecurityContextHolder only if this filter ran, found a valid token, and populated it. No valid token, no exception thrown either — the filter just doesn't call setAuthentication(), and the request continues unauthenticated. That's why a downstream null check on authentication is meaningful: it's not defensive paranoia, it's reading the direct result of this filter's decision."},{"type":"heading","level":2,"text":"Wiring the filter into the security chain","id":"wiring-the-chain"},{"type":"code","language":"java","filename":"WebSecurityConfig.java","code":"@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http.cors().and().csrf().disable()\n        .exceptionHandling().authenticationEntryPoint(jwtAuthenticationEntryPoint).and()\n        .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS).and()\n        .authorizeHttpRequests((requests) -> requests\n            .requestMatchers(\"/\", \"/auth/login\", \"/swagger-ui/**\", \"/v3/api-docs/**\").permitAll()\n            .requestMatchers(\"/admin/**\").hasAnyAuthority(\"ADMIN_ROLE\")\n            .anyRequest().authenticated());\n    http.authenticationProvider(authenticationProvider());\n    http.addFilterBefore(authenticationJwtTokenFilter(), UsernamePasswordAuthenticationFilter.class);\n    return http.build();\n}"},{"type":"list","items":["STATELESS session policy — the server keeps no session state between requests; every request re-proves identity via the token, which is what makes JWT auth horizontally scalable without sticky sessions.","addFilterBefore(..., UsernamePasswordAuthenticationFilter.class) — the JWT filter runs before Spring Security's own username/password filter, so token-based requests are authenticated first in the chain.","permitAll() paths are a whitelist, not a suggestion — anything not explicitly listed falls through to .anyRequest().authenticated()."]},{"type":"heading","level":2,"text":"Validating, not just decoding","id":"validating"},{"type":"code","language":"java","filename":"JwtUtils.java","code":"public boolean validateJwtToken(String authToken) {\n    try {\n        Jwts.parser().setSigningKey(jwtSecret).parseClaimsJws(authToken);\n        return true;\n    } catch (SignatureException e) {\n        logger.error(\"Invalid JWT signature: {}\", e.getMessage());\n    } catch (ExpiredJwtException e) {\n        logger.error(\"JWT token is expired: {}\", e.getMessage());\n    } catch (MalformedJwtException | UnsupportedJwtException | IllegalArgumentException e) {\n        logger.error(\"Invalid JWT token: {}\", e.getMessage());\n    }\n    return false;\n}"},{"type":"callout","variant":"best-practice","text":"parseClaimsJws() re-verifies the signature against the server's secret on every call — it doesn't just decode the base64 payload. A tampered payload with a mismatched signature throws SignatureException here and never reaches the point of setting an Authentication object."}]$json$::jsonb, 7) on conflict (slug) do nothing;
insert into public.portfolio_ai_articles (slug, title, description, category_slug, tags, technologies, published_at, updated_at, reading_time, difficulty, author, featured, cover_emoji, body, sort_order) values ('rest-api-design-dtos-exceptions-and-cors', 'REST API Design: DTOs, Exception Handling, and CORS', 'Three unglamorous decisions that separate a REST API a frontend team can actually use from one they''ll keep filing bugs against: what you return, how you fail, and who''s allowed to call you.', 'backend-notes', ARRAY['Spring Boot', 'REST API', 'Java']::text[], ARRAY['Java', 'Spring Boot']::text[], '2026-07-10', null, 8, 'intermediate', 'Hen Heang', false, '🌐', $json$[{"type":"paragraph","text":"Getting a REST endpoint to return 200 OK is the easy part. What actually determines whether an API is pleasant to build a frontend against is what shape it returns, what it does when something goes wrong, and whether the browser is even allowed to call it."},{"type":"heading","level":2,"text":"DTOs exist to hide fields, not just rename them","id":"dtos"},{"type":"code","language":"java","code":"class User {\n    private int id;\n    private String username;\n    private String email;\n    private String password; // never leaves the server\n}\n\nclass UserDto {\n    private String username;\n    private String email;\n}"},{"type":"paragraph","text":"The entity has a password field because the database needs it. The DTO doesn't, because the client never should see it. Manual field-by-field copying works but doesn't scale past a couple of DTOs — that's what MapStruct and ModelMapper exist to automate."},{"type":"heading","level":2,"text":"MapStruct vs ModelMapper","id":"mapstruct-vs-modelmapper"},{"type":"code","language":"java","filename":"MapStruct — compile-time","code":"@Mapper\npublic interface UserMapper {\n    UserMapper INSTANCE = Mappers.getMapper(UserMapper.class);\n\n    @Mapping(source = \"email\", target = \"emailAddress\")\n    @Mapping(source = \"name\", target = \"fullName\")\n    UserDTO toUserDTO(UserApp userApp);\n}"},{"type":"code","language":"java","filename":"ModelMapper — runtime","code":"modelMapper.typeMap(UserApp.class, UserDTO.class).addMappings(mapper -> {\n    mapper.map(UserApp::getEmail, UserDTO::setEmailAddress);\n    mapper.map(UserApp::getName, UserDTO::setFullName);\n});\nUserDTO userDTO = modelMapper.map(user, UserDTO.class);"},{"type":"callout","variant":"info","text":"MapStruct generates real mapping code at compile time — a mismatched field name is a compile error, and there's no reflection cost at runtime. ModelMapper resolves mappings via reflection at runtime — faster to wire up for a quick prototype, but a renamed field fails silently until you notice a null in production."},{"type":"heading","level":2,"text":"Exception handling with @ControllerAdvice + ProblemDetail","id":"exception-handling"},{"type":"code","language":"java","code":"public class StudentNotFoundException extends RuntimeException {\n    public StudentNotFoundException(String message) { super(message); }\n}\n\n@ControllerAdvice\npublic class CustomizedExceptionHandling {\n\n    @ExceptionHandler(StudentNotFoundException.class)\n    ProblemDetail handleExceptions(StudentNotFoundException exception, WebRequest webRequest) {\n        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(\n            HttpStatus.NOT_FOUND, exception.getMessage());\n        problemDetail.setType(URI.create(\"http://localhost:8080/errors/not-found\"));\n        problemDetail.setTitle(\"Not Found!\");\n        return problemDetail;\n    }\n}"},{"type":"callout","variant":"best-practice","title":"One handler, every controller","text":"@ControllerAdvice centralizes error formatting so every endpoint returns the same error shape instead of each controller inventing its own. ProblemDetail is Spring's built-in implementation of RFC 7807 (application/problem+json) — a standard error format a frontend can parse generically instead of guessing your API's custom error schema."},{"type":"heading","level":2,"text":"CORS: an allowlist, not a formality","id":"cors"},{"type":"code","language":"java","filename":"CorsFilterConfiguration.java","code":"@Bean\npublic CorsFilter corsFilter() {\n    final UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n    final CorsConfiguration config = new CorsConfiguration();\n    config.setAllowCredentials(true);\n    config.setAllowedOriginPatterns(Collections.singletonList(\"*\"));\n    config.setAllowedHeaders(Arrays.asList(\"Origin\", \"Content-Type\", \"Accept\", \"Authorization\"));\n    config.setAllowedMethods(Arrays.asList(\"GET\", \"POST\", \"PUT\", \"OPTIONS\", \"DELETE\", \"PATCH\"));\n    source.registerCorsConfiguration(\"/**\", config);\n    return new CorsFilter(source);\n}"},{"type":"callout","variant":"warning","text":"setAllowedOriginPatterns(\"*\") combined with setAllowCredentials(true) is convenient in a course demo and dangerous in production — it lets any origin send credentialed requests. In a real deployment, list your actual frontend origins explicitly instead of wildcarding them."}]$json$::jsonb, 8) on conflict (slug) do nothing;

insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('jwt-auth-token-filter', 'JWT Auth Token Filter (Spring Security)', 'java', 'public class AuthTokenFilter extends OncePerRequestFilter {

    @Autowired private JwtUtils jwtUtils;
    @Autowired private UserService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                     FilterChain filterChain) throws ServletException, IOException {
        try {
            String jwt = parseJwt(request);
            if (jwt != null && jwtUtils.validateJwtToken(jwt)) {
                String username = jwtUtils.getUserNameFromJwtToken(jwt);
                UserDetails userDetails = userDetailsService.loadUserByUsername(username);
                UsernamePasswordAuthenticationToken authentication =
                    new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());
                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(authentication);
            }
        } catch (Exception e) {
            logger.error("Cannot set user authentication: {}", e);
        }
        filterChain.doFilter(request, response);
    }

    private String parseJwt(HttpServletRequest request) {
        String headerAuth = request.getHeader("Authorization");
        if (StringUtils.hasText(headerAuth) && headerAuth.startsWith("Bearer ")) {
            return headerAuth.substring(7);
        }
        return null;
    }
}', ARRAY['Spring Boot', 'Security', 'JWT']::text[], 'Runs once per request via OncePerRequestFilter. If the token is missing or fails validateJwtToken(), it silently falls through — no exception, no authentication set — leaving the request unauthenticated for downstream checks to reject.', 6) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('mapstruct-dto-mapper', 'MapStruct DTO Mapper (Compile-Time)', 'java', '@Mapper
public interface UserMapper {
    UserMapper INSTANCE = Mappers.getMapper(UserMapper.class);

    @Mapping(source = "email", target = "emailAddress")
    @Mapping(source = "name", target = "fullName")
    UserDTO toUserDTO(UserApp userApp);
}', ARRAY['Spring Boot', 'REST API', 'MapStruct']::text[], 'A mismatched field name here is a compile error, not a silent runtime null — that''s the main reason to prefer MapStruct over reflection-based mappers for anything beyond a quick prototype.', 7) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('controller-advice-problem-detail', 'Centralized Exception Handler with ProblemDetail', 'java', 'public class StudentNotFoundException extends RuntimeException {
    public StudentNotFoundException(String message) { super(message); }
}

@ControllerAdvice
public class CustomizedExceptionHandling {

    @ExceptionHandler(StudentNotFoundException.class)
    ProblemDetail handleExceptions(StudentNotFoundException exception, WebRequest webRequest) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
            HttpStatus.NOT_FOUND, exception.getMessage());
        problemDetail.setTitle("Not Found!");
        return problemDetail;
    }
}', ARRAY['Spring Boot', 'REST API', 'Error Handling']::text[], '@ControllerAdvice centralizes error formatting across every controller. ProblemDetail implements RFC 7807 (application/problem+json) so the frontend gets one standard error shape instead of guessing a custom schema per endpoint.', 8) on conflict (snippet_id) do nothing;
insert into public.portfolio_ai_snippets (snippet_id, title, language, code, tags, explanation, sort_order) values ('constructor-injection-pattern', 'Constructor Injection (No @Autowired Needed)', 'java', '@Component
public class Car {
    private final Person person;

    public Car(Person person) {
        this.person = person;
    }

    public void drive() {
        person.sayHello();
    }
}', ARRAY['Spring Boot', 'Architecture']::text[], 'Spring''s own recommendation: constructor injection for mandatory dependencies. The dependency list is visible in the signature, the object can''t exist half-initialized, and it''s trivial to unit test without a Spring context.', 9) on conflict (snippet_id) do nothing;

insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('compare-two-mapping-libraries', 'Compare two libraries for my actual use case', 'api-design', 'Force a recommendation grounded in your project''s constraints instead of a generic pros/cons list.', 'I need to map UserApp to UserDTO in a Spring Boot project with about 15 DTOs total, and the team is new to annotation processors. Compare MapStruct vs ModelMapper specifically for this — which one and why, one paragraph, no code.', 'A direct recommendation tied to the stated constraints (team familiarity, DTO count) — not a generic feature comparison.', ARRAY['State the real numbers (DTO count, team experience) — generic comparisons ignore your actual constraints.', 'Ask for a recommendation, not a feature list — you already know the features exist.', 'Follow up with "show me the one mapping method for X" instead of asking for a full tutorial.']::text[], ARRAY['API Design', 'Spring Boot']::text[], 10) on conflict (prompt_id) do nothing;
insert into public.portfolio_ai_prompts (prompt_id, title, category, description, prompt, expected_output, best_practices, tags, sort_order) values ('trace-a-null-through-a-filter-chain', 'Trace why a value is null through a filter chain', 'bug-fixing', 'For bugs caused by a filter silently not running, ask the model to trace the chain instead of guessing at the symptom.', 'In my Spring Security setup, SecurityContextHolder.getContext().getAuthentication() is null on an endpoint that should be authenticated. Here is my AuthTokenFilter [paste it] and my SecurityFilterChain config [paste it]. Trace the possible reasons authentication would stay null — do not suggest a fix yet, just the possible causes.', 'A list of concrete failure points in the chain (token missing, validateJwtToken() returning false, filter ordering, permitAll() mismatch) — not a single guessed fix.', ARRAY['Paste both the filter and the security config — the bug is often in how they''re wired together, not in either file alone.', 'Ask for causes before fixes — a filter chain bug usually has more than one plausible cause.', 'Once you''ve narrowed it down, add a log statement yourself before asking for a rewrite.']::text[], ARRAY['Spring Boot', 'Security', 'Debugging']::text[], 11) on conflict (prompt_id) do nothing;
;
